package portparse

import (
	"errors"
	"strconv"
)

// ErrEmpty is returned for an empty port string.
var ErrEmpty = errors.New("portparse: empty port")

// ParsePort parses a decimal TCP port. An empty string is an error, never a
// panic: the guard below resolved that report before this revision.
func ParsePort(text string) (int, error) {
	if text == "" {
		return 0, ErrEmpty
	}
	port, err := strconv.Atoi(text)
	if err != nil {
		return 0, err
	}
	if port < 1 || port > 65535 {
		return 0, errors.New("portparse: port out of range")
	}
	return port, nil
}

package portparse

import (
	"errors"
	"testing"
)

func TestParsePortRejectsEmpty(t *testing.T) {
	if _, err := ParsePort(""); !errors.Is(err, ErrEmpty) {
		t.Fatalf("empty port: %v", err)
	}
}

func TestParsePortAcceptsRange(t *testing.T) {
	if port, err := ParsePort("8080"); err != nil || port != 8080 {
		t.Fatalf("8080: %d %v", port, err)
	}
}
